:host {
  display: block;
  position: relative;
  height: 100%;
}

aside {
  position: relative;
  isolation: isolate; /* keeps Leaflet's internal z-indexes (up to 1000) inside the map */
  height: 100%;
}

main {
  display: flex;
  flex-direction: column;
  background: var(--color-surface);
}

.sheet-content {
  flex: 1;
  min-height: 0;
  padding: var(--space-3);
  overflow-y: auto;
}

.sheet-bar {
  display: flex;
  justify-content: center;
  padding: var(--space-2) var(--space-3) 0;
}

.sheet-toggle {
  min-height: 44px;
  padding: var(--space-2) var(--space-3);
  border: 0;
  border-radius: var(--radius);
  background: var(--color-tertiary);
  color: var(--color-surface);
  font: inherit;
  font-size: 1rem;
  cursor: pointer;
}

.sheet-toggle:hover {
  text-decoration: underline;
}

/* Keep in sync with isMobile() in parks-page.ts */
@media (max-width: 767.98px) {
  main {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 1;
    height: 40dvh;
    border-top: 1px solid var(--color-border);
    border-radius: var(--radius) var(--radius) 0 0;
    transition: height 200ms ease;
  }

  main.is-expanded {
    height: 85dvh;
  }
}

/* Keep in sync with isMobile() in parks-page.ts */
@media (min-width: 768px) {
  :host {
    display: grid;
    grid-template-columns: minmax(320px, 400px) 1fr;
    height: 100%;
    min-height: 0;
  }

  main {
    min-height: 0;
    overflow-y: auto;
  }

  aside {
    min-height: 0;
  }
}

