:host {
  display: block;
}

.frame {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border-radius: var(--radius);
  background: var(--color-border);
}

img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

img.hidden {
  position: absolute;
  inset: 0;
  opacity: 0;
}

.skeleton {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    var(--color-border) 0%,
    var(--color-surface) 50%,
    var(--color-border) 100%
  );
  background-size: 200% 100%;
  animation: shimmer 1.4s ease-in-out infinite;
}

.placeholder {
  display: grid;
  place-items: center;
  height: 100%;
  color: var(--color-secondary-light);
}

@keyframes shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -100% 0;
  }
}

